import collections

def shortestSubarray(A, K):
    n = len(A)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + A[i]
    deque = collections.deque()
    res = float('inf')
    for j in range(n + 1):
        while deque and prefix[j] - prefix[deque[0]] >= K:
            res = min(res, j - deque.popleft())
        while deque and prefix[j] <= prefix[deque[-1]]:
            deque.pop()
        deque.append(j)
    return res if res != float('inf') else -1

