def minPatches(nums, n):
    # Edge case.
    if not nums or nums[-1] > n:
        nums.append(n + 1)
    patch, i, nums_len, sum_n = 0, 0, len(nums), 0
    while sum_n < n:
        if i < nums_len and nums[i] <= sum_n + 1:
            sum_n += nums[i]
            i += 1
        else:
            sum_n += sum_n + 1
            patch += 1
    return patch

